<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use Illuminate\Http\Request;use Illuminate\Support\Carbon;use Symfony\Component\HttpFoundation\StreamedResponse;
class ReportController extends Controller {
 public function summary(Request $r){$d=$r->validate(['from'=>'nullable|date','to'=>'nullable|date|after_or_equal:from']);$from=Carbon::parse($d['from']??now()->startOfMonth())->startOfDay();$to=Carbon::parse($d['to']??now())->endOfDay();$u=$r->user();$entries=$u->habits()->with(['entries'=>fn($q)=>$q->whereBetween('entry_date',[$from->toDateString(),$to->toDateString()])])->get()->flatMap->entries;return response()->json(['range'=>['from'=>$from->toDateString(),'to'=>$to->toDateString()],'habits'=>['total'=>$u->habits()->count(),'active'=>$u->habits()->where('is_active',true)->count()],'entries'=>['completed'=>$entries->where('status','completed')->count(),'partial'=>$entries->where('status','partial')->count(),'missed'=>$entries->where('status','missed')->count()],'tasks'=>['total'=>$u->tasks()->whereBetween('created_at',[$from,$to])->count(),'completed'=>$u->tasks()->where('status','completed')->whereBetween('updated_at',[$from,$to])->count(),'overdue'=>$u->tasks()->whereNotIn('status',['completed'])->where('due_at','<',now())->count()],'focus_minutes'=>(int)$u->focusSessions()->whereBetween('started_at',[$from,$to])->sum('actual_minutes'),'goals'=>$u->goals()->select('id','title','progress','status','due_at')->get()]);}
 public function csv(Request $r): StreamedResponse {$d=$r->validate(['from'=>'nullable|date','to'=>'nullable|date|after_or_equal:from']);$from=Carbon::parse($d['from']??now()->startOfMonth())->toDateString();$to=Carbon::parse($d['to']??now())->toDateString();$u=$r->user();$rows=$u->habits()->with(['entries'=>fn($q)=>$q->whereBetween('entry_date',[$from,$to])])->get();return response()->streamDownload(function()use($rows){$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['habit','date','status','value','duration_minutes','note']);foreach($rows as $h)foreach($h->entries as $e)fputcsv($out,[$h->name,$e->entry_date->format('Y-m-d'),$e->status,$e->value,$e->duration_minutes,$e->note]);fclose($out);},'habittrack-report.csv',['Content-Type'=>'text/csv; charset=UTF-8']);}
 public function backup(Request $r){$u=$r->user();return response()->json(['format'=>'habittrack-backup-v1','exported_at'=>now()->toIso8601String(),'user'=>['name'=>$u->name,'email'=>$u->email],'settings'=>$u->settings,'habits'=>$u->habits()->with('entries')->get(),'goals'=>$u->goals()->with(['tasks','milestones'])->get(),'tasks'=>$u->tasks()->get(),'focus_sessions'=>$u->focusSessions()->get(),'daily_notes'=>$u->dailyNotes()->get(),'reward'=>$u->reward,'badges'=>$u->badges()->get()])->header('Content-Disposition','attachment; filename="habittrack-backup.json"');}
}